#include "GameplayRules3D.h"
#include <cmath>
#include <iostream>
using namespace GameplayLab;using namespace Aevrynd;
int main(){Rules3D r;r.SetCamera(CameraMode::FirstPerson);r.SetCamera(CameraMode::ThirdPerson);r.SetCamera(CameraMode::GodView);r.SetHeadroom(false);r.Tick({{},false,false,true});r.Tick({{},false,false,true});if(!r.Crouched()||r.GetStats().headroomRejected!=1)return 1;r.SetHeadroom(true);r.Tick({{},false,false,true});for(int i=0;i<60;++i)r.Tick({{0,0,1},true,i==0});if(r.CharacterPosition().z<6||r.GetStats().jumps!=1)return 2;for(unsigned c=0;c<6;++c){r.SetPaletteCategory(PaletteCategory(c));if(!r.Place({float(c)+.3f,0,float(c)+.7f},c==1))return 3;}if(r.Entities().size()!=6||!r.Undo()||!r.Redo())return 4;if(!r.BeginGrab(r.Entities()[1].id,7.9f)||r.BeginGrab(r.Entities()[1].id,1)||!r.Grabbed())return 5;r.EndGrab();if(r.BeginGrab(r.Entities()[1].id,8.1f))return 6;r.SetLighting(LightingPhase::Day);auto d=r.EvaluateLighting();r.SetLighting(LightingPhase::Night);auto n=r.EvaluateLighting();if(d.intensity<=n.intensity||n.exposure>=d.exposure)return 8;for(std::size_t i=r.Entities().size();i<Rules3D::MaximumEntities;++i)if(!r.Place({float(i%16),0,float(i/16)}))return 9;if(r.Place({0,0,0})||r.GetStats().placementRejected!=1)return 10;std::cout<<"ticks="<<r.GetStats().ticks<<" entities="<<r.Entities().size()<<"\n";return 0;}
